<script lang="ts">
  import { editor } from '../stores/editor.svelte';
  const endpoint=$derived(editor.environment?.mcp_url ?? null);
  const config=$derived(JSON.stringify({mcpServers:{ctg:{type:'http',url:endpoint ?? 'http://127.0.0.1:7414/mcp'}}},null,2));
  let copied=$state(false);
  async function copy():Promise<void>{try{await navigator.clipboard.writeText(config);copied=true;}catch{editor.notify('Clipboard unavailable. Select and copy the configuration below.',true);}}
</script>
